const post = $json;
const spec = typeof post.visual_spec === 'string' ? JSON.parse(post.visual_spec) : (post.visual_spec || {});
const layoutGuide = { process_flow: 'a clearly ordered TOP-TO-BOTTOM process with three to five distinct steps on one central vertical spine', layered_architecture: 'a vertically layered technical architecture with visible boundaries between layers', comparison: 'a balanced side-by-side technical comparison with a clear shared center or divider', cause_effect: 'a visible cause-to-consequence chain with branching outcomes when needed', cycle: 'a closed technical feedback loop with a clear clockwise reading order' };
const stages = Array.isArray(spec.stages) ? spec.stages : [];
const connections = Array.isArray(spec.connections) ? spec.connections : [];
const stagePlan = stages.map((stage) => '- ' + stage.label + ': ' + stage.description + ' [icon=' + stage.icon + ', state=' + stage.state + ']').join('
');
const connectionPlan = connections.map((edge) => edge.from + ' -> ' + edge.to + ' [' + edge.type + ']').join(', ');
const visualRules = 'Use case: infographic-diagram. Create only the text-free technical illustration layer for an educational Turkish LinkedIn infographic. The chosen visual grammar is ' + (layoutGuide[spec.layout_type] || layoutGuide.process_flow) + '. Every component must have a distinct technical role and the relationships must be understandable without labels. Use recognizable industrial and enterprise technology components appropriate to the stage plan. Use explicit cables, arrows, boundaries, grouping and scale to communicate the mechanism. Connection semantics: allowed/flow in emerald, blocked in restrained red with a clear stop symbol, conditional in restrained amber, bidirectional with two arrowheads. Do not invent extra stages or unrelated objects. Leave seamless unframed negative space near the outer edges for deterministic callouts and a quiet lower strip for takeaways. Never draw blank rectangles, empty cards, placeholder panels, UI frames, outlined slots, fake dashboards, words, letters, numbers, logos, watermarks or pseudo-writing. The final published canvas is portrait 1200x1500. Build the technical narrative vertically from top to bottom, centered on one continuous vertical spine. Place the first stage near the upper quarter, intermediate stages down the middle, and the final stage above the lower safe zone. Use a compact central width; never arrange the main stages side by side. Keep clear side gutters for callouts. Reserve the entire lower 20 percent as uninterrupted empty obsidian background: no devices, branches, cables, arrows, shadows or glow may enter it. Every object belonging to the final stage must be fully visible above that safe zone. The generated source layer is square 1200x1200 but must preserve this portrait reading direction.';
const prompt = visualRules + '

Layout type: ' + (spec.layout_type || 'process_flow') + '
Technical concept: ' + (spec.technical_title || post.pillar) + '
Post theme: ' + post.pillar + '
Visual brief: ' + post.image_brief + '

Stages:
' + stagePlan + '

Connections: ' + connectionPlan;
return [{ json: { request_body: { model: 'gpt-image-2.5-flare', prompt, size: '1200x1200', quality: 'high', output_format: 'png', background: 'opaque' } } }];

const requestBody = { ...$json.request_body };
requestBody.prompt += '

BRAND ART DIRECTION: Match emrecancioglu.com: obsidian #0A0B0D background, graphite #131519 and #1A1D22 surfaces, emerald #34D399 and #10B981 accents, warm off-white #ECECEA and muted gray #9A9A97. Use premium technical cutaway or clean semi-3D vector realism, precise geometry, controlled depth and restrained emerald reflections. No electric blue, purple, rainbow gradients, excessive neon, plastic toy-like objects, oversized shields or cinematic cover-art composition. Explanation is more important than spectacle. Reserved negative space must remain continuous background with absolutely no empty gray boxes, placeholder cards, decorative panels or frames.';
requestBody.prompt += '

ORIENTATION LOCK: The destination is a portrait LinkedIn canvas. All primary stages must form one top-to-bottom visual chain around the centerline. Do not use a wide left-to-right panorama. External callouts will connect horizontally from a side gutter to the matching stage at the same height. Do not draw stage numbers, numbered circles, badges or labels inside the illustration.';
return [{ json: { request_body: requestBody } }];

const response = $json;
if (response.error) throw new Error(`OpenAI image error: ${JSON.stringify(response.error)}`);
const base64 = response.data?.[0]?.b64_json;
if (!base64) throw new Error('Gorsel base64 verisi bulunamadi');
const post = $('Select Draft').first().json;
const fileName = `${post.id}.png`;
const imagePath = `/data/content/generated/${fileName}`;
return [{
  json: {
    post_id: post.id,
    image_path: imagePath,
    image_model: 'gpt-image-2.5-flare',
    image_usage: response.usage ?? null
  },
  binary: {
    data: {
      data: base64,
      mimeType: 'image/png',
      fileName,
      fileExtension: 'png'
    }
  }
}];
